// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests social post records into car and demand rows
// Flo: record JSON in > assert fields, masked phone, buyer row, bad input
// I/O: strings > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const soci = @import("pa-carz-soci.zig");
const SELL = "{\"kind\":\"face\",\"id\":\"p1\",\"url\":\"https://www.facebook.com/groups/12/posts/p1\",\"text\":\"Toyota Fortuner 2017 số sàn, 84.000 km, máy dầu, bán gấp giá 520 triệu. Liên hệ 0966.353.678 ở Bình Dương\",\"auth\":\"Nguyen Van A\",\"src\":\"Mua ban oto\",\"posted\":1795000000000}";
const BUYR = "{\"kind\":\"zalo\",\"id\":\"z9\",\"url\":\"https://zalo.me/g/abc/z9\",\"text\":\"Cần mua Mazda CX-5 đời 2020 tầm 700tr, ai có bán liên hệ\",\"auth\":\"Tran B\"}";
test "sell post: make, year, km, price, gearbox, fuel, province, masked phone, owner only in contact fields" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const carz = try soci.sociPars(aren.allocator(), "https://www.facebook.com/groups/12/posts/p1", SELL, 2026); try std.testing.expectEqualStrings("facebook.com", carz.site); try std.testing.expectEqualStrings("p1", carz.lidz); try std.testing.expectEqualStrings("Toyota", carz.make); try std.testing.expectEqualStrings("Fortuner", carz.modl); try std.testing.expectEqual(@as(i64, 2017), carz.year); try std.testing.expectEqual(@as(i64, 84000), carz.kmzz); try std.testing.expectEqual(@as(i64, 520_000_000), carz.pric); try std.testing.expectEqualStrings("MT", carz.gear); try std.testing.expectEqualStrings("DSL", carz.powr); try std.testing.expectEqualStrings("used", carz.cond); try std.testing.expectEqualStrings("Bình Dương", carz.prov); try std.testing.expectEqualStrings("private", carz.sell); try std.testing.expectEqualStrings("0966353678", carz.phon); try std.testing.expect(std.mem.indexOf(u8, carz.text, "0966") == null); try std.testing.expect(std.mem.indexOf(u8, carz.text, "[tel]") != null); try std.testing.expectEqualStrings("Nguyen Van A", carz.cnam); try std.testing.expectEqualStrings("Mua ban oto", carz.cdes); try std.testing.expectEqual(@as(i64, 1795000000000), carz.post); try std.testing.expectEqualStrings("", carz.shop); }
test "buy post: demand row with no price, budget in xtra, never a sell row" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const carz = try soci.sociPars(aren.allocator(), "https://zalo.me/g/abc/z9", BUYR, 2026); try std.testing.expectEqualStrings("buyer", carz.sell); try std.testing.expectEqual(@as(i64, 0), carz.pric); try std.testing.expectEqualStrings("Mazda", carz.make); try std.testing.expectEqualStrings("", carz.trim); try std.testing.expectEqual(@as(i64, 2020), carz.year); try std.testing.expect(std.mem.indexOf(u8, carz.xtra, "\"intent\":\"buy\"") != null); try std.testing.expect(std.mem.indexOf(u8, carz.xtra, "700000000") != null); try std.testing.expect(soci.buyIntent("cần mua xe", "")); try std.testing.expect(!soci.buyIntent("cần mua xe, cần bán xe cũ", "")); try std.testing.expect(!soci.buyIntent("cần mua", "sell")); try std.testing.expect(soci.buyIntent("hello", "buy")); }
test "dealer role keeps the shop name, an old year never stays new" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const body = "{\"kind\":\"face\",\"id\":\"d1\",\"text\":\"Hyundai Accent 2015 xe mới về giá 300 triệu\",\"auth\":\"Showroom Binh\",\"role\":\"dealer\"}"; const carz = try soci.sociPars(aren.allocator(), "https://www.facebook.com/d1", body, 2026); try std.testing.expectEqualStrings("dealer", carz.sell); try std.testing.expectEqualStrings("Showroom Binh", carz.shop); try std.testing.expectEqualStrings("", carz.cond); try std.testing.expectEqual(@as(i64, 300_000_000), carz.pric); }
test "hosts, record sniff, bad json, utf8 cut, price scan" { try std.testing.expect(soci.sociHost("facebook.com")); try std.testing.expect(soci.sociHost("m.facebook.com")); try std.testing.expect(soci.sociHost("zalo.me")); try std.testing.expect(!soci.sociHost("notfacebook.com")); try std.testing.expect(!soci.sociHost("example.com")); try std.testing.expect(soci.isReco(SELL)); try std.testing.expect(!soci.isReco("<html><body>x</body></html>")); try std.testing.expect(!soci.isReco("{}")); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expectError(error.BadRecord, soci.sociPars(aren.allocator(), "https://zalo.me/x", "{\"kind\":\"zalo\",\"posted\":\"abc\"}", 2026)); try std.testing.expectEqualStrings("a", soci.cutzUtf8("aấ", 2)); try std.testing.expectEqualStrings("aấ", soci.cutzUtf8("aấ", 4)); try std.testing.expectEqual(@as(i64, 0), soci.pricScan("giá 520000000")); try std.testing.expectEqual(@as(i64, 0), soci.pricScan("gọi 0903123456")); try std.testing.expectEqual(@as(i64, 2_500_000_000), soci.pricScan("giá 2,5 tỷ")); try std.testing.expectEqual(@as(i64, 0), soci.pricScan("")); }
test "engine-shaped records (fb feed, za feed) parse: za chat url host, fb record without posted" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const zalo = "{\"kind\":\"zalo\",\"id\":\"00aa11bb22cc33dd\",\"url\":\"https://chat.zalo.me/c/99ff88ee77dd66cc/m/00aa11bb22cc33dd\",\"text\":\"Bán Ford Ranger 2019 số tự động 45.000 km giá 650 triệu, 0903 123 456\",\"src\":\"Bán xe HN\",\"auth\":\"Cy\",\"role\":\"private\",\"posted\":1795000000000}"; const carz = try soci.sociPars(aren.allocator(), "https://chat.zalo.me/c/99ff88ee77dd66cc/m/00aa11bb22cc33dd", zalo, 2026); try std.testing.expect(soci.sociHost(carz.site)); try std.testing.expectEqualStrings("chat.zalo.me", carz.site); try std.testing.expectEqualStrings("Ford", carz.make); try std.testing.expectEqual(@as(i64, 2019), carz.year); try std.testing.expectEqual(@as(i64, 650_000_000), carz.pric); try std.testing.expectEqualStrings("AT", carz.gear); try std.testing.expectEqualStrings("0903123456", carz.phon); const face = "{\"kind\":\"face\",\"id\":\"555001\",\"url\":\"https://www.facebook.com/groups/12/posts/555001\",\"text\":\"Toyota Fortuner 2017\\nsố sàn, 84.000 km, giá 520tr\",\"src\":\"/groups/12/\",\"auth\":\"Nguyen Van A\",\"role\":\"private\"}"; const fcar = try soci.sociPars(aren.allocator(), "https://www.facebook.com/groups/12/posts/555001", face, 2026); try std.testing.expectEqual(@as(i64, 0), fcar.post); try std.testing.expectEqual(@as(i64, 520_000_000), fcar.pric); try std.testing.expectEqualStrings("Toyota", fcar.make); }
